        import time

        LANGUAGE_WRAPPER = 'Let {n_points} points x_1, x_2, ..., x_{n_points} lie in Euclidean space R^{[dimension]} and satisfy sum_{k=1}^{n_points} x_k = 0 and sum_{k=1}^{n_points} ||x_k||^2 = {total_energy}. Determine the minimum possible value of max_{1 <= i < j <= n_points} ||x_i - x_j||, expressed in simplest radical form.'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        from math import gcd

def generator(rng):
    # choose dimension d >= 2
    dimension = rng.randint(2, 7)
    # choose multiplier m >= 2 so that n is a multiple of d+1 (to ensure tightness via regular simplex construction)
    m = rng.randint(2, 60)
    n_points = m * (dimension + 1)
    # choose a positive reduced rational for total_energy
    # pick numerator and denominator in [1, 120] to get reasonably varied radicals
    a = rng.randint(1, 120)
    b = rng.randint(1, 120)
    g = gcd(a, b)
    a //= g
    b //= g
    total_energy_num = a
    total_energy_den = b
    if b == 1:
        total_energy = str(a)
    else:
        total_energy = f"{a}/{b}"
    return {
        'n_points': n_points,
        'dimension': dimension,
        'total_energy': total_energy,
        'total_energy_num': total_energy_num,
        'total_energy_den': total_energy_den
    }

        from math import gcd, sqrt

def verifier(assign):
    # Basic presence and type checks
    try:
        n = int(assign.get('n_points'))
        d = int(assign.get('dimension'))
        a = int(assign.get('total_energy_num'))
        b = int(assign.get('total_energy_den'))
    except Exception:
        # Missing or invalid types
        return (False, None)
    # Domain constraints
    if d < 2:
        # Must be at least planar to invoke nontrivial Jung constant
        return (False, None)  # invalid dimension
    if n <= d:
        # Need at least d+1 points for non-degenerate simplex arguments
        return (False, None)
    if a <= 0 or b <= 0:
        return (False, None)  # energy must be positive
    # Ensure n is a multiple of d+1 to guarantee attainability via a regular simplex replication
    if n % (d + 1) != 0:
        return (False, None)
    # Reduced rational check for total_energy
    if gcd(a, b) != 1:
        # Require lowest terms to avoid ambiguous representations
        return (False, None)
    S = a / b
    # Jung constant in R^d: any set of diameter D fits in a ball of radius j_d * D where j_d^2 = d/(2(d+1))
    # Lower bound derived: D >= sqrt((2(d+1)/d) * S / n)
    num = 2 * (d + 1) * a
    den = d * n * b
    g = gcd(num, den)
    num //= g
    den //= g
    # Difficulty enforcement: ensure this bound is strictly larger than the trivial average-pairwise bound
    trivial_sq = 2 * S / (n - 1)
    bound_sq = (2 * (d + 1) / d) * S / n
    if not (bound_sq > trivial_sq):
        # If not strictly stronger, the instance is too easy or degenerate
        return (False, None)
    # Prepare radical answer string sqrt(num/den) or sqrt(num) / sqrt(den)
    # We keep as \sqrt{num/den} in reduced fraction form
    if den == 1:
        ans = f"\\sqrt{{{num}}}"
    else:
        ans = f"\\sqrt{{{num}/{den}}}"
    return (True, ans)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

